package com.northstarbank.console.service;import com.northstarbank.console.domain.*;import java.nio.charset.StandardCharsets;import java.nio.file.*;import java.util.*;import org.springframework.beans.factory.annotation.Value;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.*;
@Configuration class ConsoleSeeder{@Bean CommandLineRunner seedDocuments(DocumentRepository docs,@Value("${app.upload-dir}")String dir){return args->{if(docs.count()>0)return;Path base=Path.of(dir).toAbsolutePath().normalize();Files.createDirectories(base);for(int i=1;i<=6;i++){String ref=UUID.randomUUID().toString();String text="Northstar mock case document "+i+". No real customer data.";Files.writeString(base.resolve(ref),text,StandardCharsets.UTF_8,StandardOpenOption.CREATE_NEW);docs.save(new CaseDocument(String.format("C%04d",i),i%2==0?"internal":"customer_disclosable","EMP002","case-evidence-"+i+".txt","text/plain",text.length(),ref));}};}@Bean CommandLineRunner writeStatements(@Value("${app.statement-dir}")String dir){return args->{Path base=Path.of(dir).toAbsolutePath().normalize();Files.createDirectories(base);for(int i=1;i<=6;i++){Path file=base.resolve("statement-2026-0"+i+".csv");if(Files.notExists(file))Files.writeString(file,"date,reference,description,amount\n2026-0"+i+"-01,TX00000"+i+" Opened statement,0.00\n",StandardCharsets.UTF_8);}};}}
